It seems that the problem happens when a mobile device is going to sleep:
```
[ 2165.360317]  (0)[399:systemd-journal]Restarting tasks ... 
[ 2165.369641]  (0)[399:systemd-journal]systemd-journald[399]: Failed to create new runtime journal: Interrupted system call
```
The first line is printed by the kernel in `kernel/power/process.c:thaw_processes()`:
```
void thaw_processes(void)
{
        struct task_struct *g, *p;
        struct task_struct *curr = current;

        trace_suspend_resume(TPS("thaw_processes"), 0, true);
        if (pm_freezing)
                atomic_dec(&system_freezing_cnt);
        pm_freezing = false;
        pm_nosig_freezing = false;

        oom_killer_enable();

        printk("Restarting tasks ... ");

        __usermodehelper_set_disable_depth(UMH_FREEZING);
        thaw_workqueues();

        read_lock(&tasklist_lock);
        for_each_process_thread(g, p) {
                /* No other threads should have PF_SUSPEND_TASK set */
                WARN_ON((p != curr) && (p->flags & PF_SUSPEND_TASK));
                __thaw_task(p);
        }
        read_unlock(&tasklist_lock);

        WARN_ON(!(curr->flags & PF_SUSPEND_TASK));
        curr->flags &= ~PF_SUSPEND_TASK;

        usermodehelper_enable();

        schedule();
        printk("done.\n");
        trace_suspend_resume(TPS("thaw_processes"), 0, false);
}
```

